int pepper_prepare_rotation(void *ctx, const char *from_frame, const char *to_frame, void **query);
void pepper_rotation_query_free(void *query);
/* n column-major 3x3 (6x6) matrices */
int pepper_query_rotation(void *ctx, void *query, int n, const double *ets, double *rotations);
int pepper_query_transform(void *ctx, void *query, int n, const double *ets, double *xforms);

